	//   > 島さん「エンディングは5000ｍにします。関係する扉周りの設定も。コイン出現なども。」
	//
	//     ★★変えたのは**距離だけ**です（★仕組み・演出・クレジットは1ドットも変えていない）。
	//     ★あわせて動かしたもの: ★`PICK_FROM_M`（拾えるコイン）と
	//       ★`js/shell.js` のテストモード（★TEST 4950m）
	//
	//   ★★★**これは下の「扉と鍵」（`GATE_ON`。★いまも保留中）とは別物です。**
	//
	//     | | 扉と鍵（`GATE_ON = 0`・保留中） | ★★ゴールの扉（これ） |
	//     |---|---|---|
	//     | 役目 | ★**通せんぼ**（鍵が無いと行き止まり） | ★★**到達点**（着いたら必ず開く） |
	//     | 場所 | 140m | ★★**5000m** |
	//     | 鍵 | ★要る | ★★**要らない** |
	//
	//   ★★★**AIへ: `GATE_ON` を 1 に戻さないこと。** ★あちらは保留のままです。
	//     ★借りているのは**絵だけ**（`js/gate-art.js`。★これも仮の絵）。
	//
	// ■ ★★もとの 10000m は「実測してから」決めた距離でした（★当てずっぽうではない）
	//
	//     かかる時間     … ★★**約13分**（育てながら走った場合。★何も買わないと24分）
	//     くぐる障害物   … 約380〜400個
	//     そのときの育ち … SPEED Lv18 / STAMINA Lv18 / COIN Lv35 あたり
	//     届くか         … ★ミス5%までのプレイなら **8回中7回**届く。
	//                      ★ミス10%だと 4000〜6500m で力尽きる
	//
	//   ★★★**そのうえで島さんが 5000m に決めました**（2026-08-23）。
	//     ★上の実測でいちばん引っかかっていたのが**「13分は長い」**でした
	//       （★★ミス10%のプレイは 4000〜6500m で力尽きる ＝ **届かない人がいた**）。
	//     ★★5000m は**その手前**なので、★★★**同じ腕前でも届くようになる**。
	//     ★かかる時間の目安 … ★★**約6分半**（★育てながら走った場合）
	//
	//   → ★★★**「上手い人だけが見られる」ではなく「ちゃんと育てた人が見られる」**位置。
	//   ★おまけ: 封印してある技（KICKFLIP / POP ＝ 220,000）は
	//     **3000m の手前でお金が届く** ＝ ★道中で技が戻ってくる
	//
	// ■ ★エンディングの段取り（★★どこでもタップで**ショートカット**できる）
	//
	//     ① 扉が開く（`GOAL_OPEN_MS`）
	//     ② ★★**白い光が広がる**（`GOAL_LIGHT_MS`）
	//     ③ まん中に3行 … CONGRATULATIONS / 5000M / CONTINUE（★点滅）
	//        （★数字は `GOAL_M` から作るので、★★**距離を変えても自動で追従**します）
	//     ④ ★もう一度タップ ＝ **CONTINUE**。★育てたものはそのままで、**その先へ**
	//
	//   ★★★**暗転（GAMEOVER）は黒、こちらは白。★対にしてあります。**
	//     ★どちらも「横の行を `FADE_ORDER` の順に塗る」やり方。★半透明は使いません
	//     （→ `OVER_FADE_MS` の説明。★重ねると 33色の外の色が出るため）
	//
	//   ★★★**CONTINUE で育てたものを消さないこと**（島さんの指定「その後は②へ」）。
	//     ★6分半かけて組んだビルドが、**達成した直後に消える**のがいちばん痛い。
	//     ★消えるのは、これまでどおり **GAMEOVER のときだけ**
	// ============================================================
	var GOAL_ON       = 1;       // ★0 にすると仕組みごと止まる（★扉も出ない）
	// ★★★★ここを変えたら、いっしょに動かすものが3つあります（★ばらけると意味が壊れる）:
	//     ① `PICK_FROM_M`（拾えるコイン。★ゴールの先に出る約束）
	//     ② `js/shell.js` の `startM`（★テストモード。★ゴールの50m手前）
	//     ③ ★画面の文字は `{M}` で自動（★手で書き換えない）
	var GOAL_M        = 5000;    // ★★ここに扉が立っている（メートル）★2026-08-23 島さんの指定
	var GOAL_OPEN_MS  = 600;     // ★①扉が開いたのを見せる時間
	var GOAL_LIGHT_MS = 900;     // ★②白い光が広がりきるまで
	var C_GOAL_LIGHT  = 29;      // ★★白（★GAMEOVER の黒と対）
	var C_GOAL_TITLE  = 17;      // ★1行目。17=赤（★GAMEOVER の文字と同じ色 ＝ 対の関係）
	var C_GOAL_TEXT   = 9;       // ★2行目以降。9=まっ黒（★白地なので黒が読みやすい）
	var GOAL_BLINK_MS = 450;     // ★CONTINUE が点いたり消えたりする間隔
	// ============================================================
	// ★★★★ページは4秒で切り替わる（2026-08-23 島さんの指定）
	// ============================================================
	//
	//   > 島さん「エンディングでページが切り替わるのは4秒間に設定してください。
	//   >   画面タップでの省略は可能だがタップ音は必要ないです。
	//   >   切り替わる効果としてフェードインとフェードアウトを入れてください。」
	//
	//   ★★★**フェードに半透明は使いません**（★この世界の色が濁るため）。
	//     ★暗転・白い光とまったく同じ「**横の行を塗る**」やり方（`FADE_ORDER`）で、
	//     ★★**白く覆っていく／覆いを外していく**ことで、出入りを作っています。
	//
	//   ★★★**最後のページは自動で進みません**（★`CONTINUE` を待つ ＝ 島さんが決めた形）
	var GOAL_PAGE_MS  = 4000;    // ★★1ページを見せる長さ（島さんの指定「4秒間」）
	var GOAL_FADE_MS  = 350;     // ★出るとき・消えるときの片道
	// ★★★★扉の前後、これだけ**何も置かない**（メートル）。2026-08-23 島さんの指定
	//   > 島さん「扉前後20ｍは障害物などおかないようにしてください。」
	//   ★★「など」＝ ★コーン・★丘の敵・★拾えるコイン **全部**。
	//   ★★★13分走った先の**到達の瞬間**を、★障害物で邪魔しないため
	var GOAL_CLEAR_M  = 20;

	// ============================================================
	// ■■■ ★★★★二段ジャンプを授かる（2026-08-22 島さんの指定）■■■
	// ============================================================
	//
	//   > 島さん「エンディングでコンテニュー後画面タップで暗転し
	//   >   一秒後画面に JUNP の文字表示お願いします。
	//   >   さらに一秒後喜びの効果音とともに JUNP の文字の横に×２を表示してください。
	//   >   ここからは二段ジャンプ可能とします。
	//   >   仕様 ジャンプ中にタップでもう一度ジャンプできる。」
	//
	//   ★★★**これは、この作品の古い決まりを島さん自身が上書きしたものです。**
	//
	//     これまで … 「★空中で押しても二段跳びにならない」
	//                （★1ボタンでも「跳ぶ位置を決める」駆け引きを残すため）
	//     ★これから … ★★**5000m を走りきった人にだけ、二段ジャンプが渡る**
	//
	//   ★★決まりは**まだ生きています**。★変わったのは「ご褒美で外れる」ようになったこと。
	//     ★★★**授かる前は、いままでどおり空中で押しても何も起きません**
	//       （★`test/ollie.test.js` がそこを見張り続けています）。
	//
	//   ■ ★段取り（★時間は島さんが指定したとおり）
	//
	//       3ページ目の CONTINUE をタップ
	//         → ★暗転（`GIFT_FADE_MS`）
	//         → ★★1秒後に **JUMP**（`GIFT_WORD_MS`）
	//         → ★★さらに1秒後に **喜びの音 ＋ ×2**（`GIFT_X2_MS`）
	//         → ★タップで走り出す（★ここから二段ジャンプ）
	//
	//   ★★**待っているあいだのタップは効きません**（★島さんが「1秒後」と決めた間を守るため）。
	//
	//   ■ ★★★AIへ: 文字について
	//     ★島さんの原文は **「JUNP」** ですが、**JUMP**（つづりの直し）にしてあります。
	//     ★★`JUNP` のままがよければ `GIFT_WORD` の1か所を書き換えるだけです
	//
	//   ■ ★★二段ジャンプは「そのランのあいだだけ」
	//     ★死んだら消えます（★コイン・レベル・技・道具とまったく同じ）。
	//     ★★この作品の芯（**残るのは BEST だけ**）を崩さないため
	var DJ_ON        = 1;        // ★0 にすると仕組みごと止まる（★授からない）
	var DJ_MAX       = 2;        // ★★1回の滞空で跳べる回数（2 = 二段ジャンプ）
	var GIFT_FADE_MS = 300;      // ★暗転にかける時間
	var GIFT_WORD_MS = 1000;     // ★★暗転してから「JUMP」が出るまで（島さん「一秒後」）
	var GIFT_X2_MS   = 1000;     // ★★「JUMP」から「×2」が出るまで（島さん「さらに一秒後」）
	var GIFT_WORD    = "JUMP";   // ★★出す文字（★島さんの原文は「JUNP」）
	var GIFT_MARK    = "×2";     // ★横に出す印
	var C_GIFT_WORD  = 16;       // ★JUMP の色。16=生成り（★暗い画面で読める）
	var C_GIFT_MARK  = 19;       // ★★×2 の色。19=黄（★ご褒美なので明るく）

	// ============================================================
	// ★★★★エンディングの3ページ —— ★島さんの持ち場（2026-08-22 島さんの指定）
	// ============================================================
	//
	//   > 島さん「エンディングに挿し絵を追加したいです。
	//   >   10000ｍの画面に takibi.png
	//   >   → 二ページ目、私 tennto.png
	//   >   → 三ページ目、協力者 kuruma.png」
	//   > 島さん「エンディングでは「Shima(私)」と「S.S(協力者)」と「S.T(協力者)」を
	//   >   クレジットに追加してください」
	//
	//   ★★**フォントにあるのは「大文字・数字・.」だけ**なので `SHIMA` と書いています
	//     （★小文字は `m` の1文字しかありません → `js/font.js`）。
	//
	//   ★★★**名前も並びもここを書き換えるだけ**で変わります（★ページを足しても崩れません）:
	//     ・`art`   … そのページに出す挿し絵の名前（→ `js/ending-art.js`）
	//     ・`lines` … 出す文字。`t` = 文字 / `hi` = 1 なら赤で目立たせる
	//     ・`{M}`   … ★ゴールの距離（いまは 5000m）に置き換わる合言葉
	//
	//   ★★挿し絵の**置き場所は島さんが決めています**（★240×160 の紙のどこに描いたか）。
	//     ★AIは1ドットも動かしていません。★文字のほうが**挿し絵を避けて**上に並びます
	var GOAL_PAGES = [
		// ★1ページ目 …… 着いたこと
		{ art: "takibi", lines: [
			{ t: "CONGRATULATIONS", hi: 1 },
			{ t: "{M}" }
		] },
		// ★2ページ目 …… 私（島さん）
		{ art: "tennto", lines: [
			{ t: "CREATED BY" },
			{ t: "SHIMA", hi: 1 }
		] },
		// ★3ページ目 …… 協力者
		{ art: "kuruma", lines: [
			{ t: "SPECIAL THANKS" },
			{ t: "S.S   S.T", hi: 1 }
		] }
	];

	// ============================================================
	// ■■■ ★★★扉と鍵 —— 「ルールの壁」（2026-08-16 / Phase C）■■■
	// ============================================================
	//
	//   島さん（2026-08-16）:
	//   > 「もう一回走りたいと感じましたが、**すぐに成長の限界値に達して**終わりました」
	//
	//   ★★実測で分かったこと: **数値では無限に難しくできない。**
	//     ・越えられる幅 ＝ 空中の時間 × 走る速さ（＝ JUMP と SPEED の掛け算）
	//     ・画面は 240ドット。障害物はどうやっても **190ドット**あたりが限界
	//     ・★**JUMP を1つも買わなくても、SPEED だけで Lv11 で全部越えられる**
	//
	//   → ★★★**壁を「数値」ではなく「ルール」にする。**
	//      **扉は、どれだけ強くなっても開かない。鍵を持っているときだけ開く。**
	//
	//   ★★作りたいのは、この輪:
	//
	//     ？？？ → 扉を発見 →「何だこれ？」→ 鍵を発見 →「これか！」
	//     → 再び扉へ → ★突破 →「この先には何がある？」→ もっと走る
	//
	//   ★★★**画面に文字で説明を出さない**（島さん「プレイヤー自身が気付くことが重要」）。
	//     扉の**鍵穴の絵**だけが手がかり。
	//
	// ■ ★★下の数字は「初期値」であって仕様ではない
	//     ★実測（複数の種・複数ラン）を見てから決める。
	//     ★★**1回の結果だけを根拠に動かさないこと**（→ `docs/decisions.md`）
	// ============================================================
	// ★★★2026-08-16、島さんの指定で**保留**にした:
	//   > 「キャンプと異世界への扉は保留。非表示にして進めて」
	//   ★★消したのではない。**0 にしてあるだけ**なので、1 に戻せばそのまま復活する
	//   ★テストも `GATE_ON` を見て、保留中は飛ばすようにしてある
	var GATE_ON   = 0;      // ★1 にすると扉と鍵が戻る
	// ★★★扉の場所は**実測で決めた**（2026-08-16）。★当てずっぽうではない
	//
	//   観測事実 … 30ラン回して最大到達 257m。★アップグレードを買い切っても **230m で頭打ち**。
	//               → ★初期値の 300m には**永久に届かなかった**（＝ 輪が閉じない）
	//   仮説     … 300m が、いまの経済で到達できる距離を超えている
	//   変更     … 8通りの遊び方 × 12ラン の到達距離を測り、そこから選んだ:
	//
	//                 扉120m … 8/8 が届く（初回は中央 4ラン目・最短1ラン目）
	//               ★扉140m … 8/8 が届く（初回は中央 5ラン目）  ←★これにした
	//                 扉160m … 6/8 しか届かない
	//                 扉180m … 2/8 しか届かない
	//
	//   ★★140m にした理由: **1ラン目でいきなり当たらない**こと。
	//     ★先に「走る → 稼ぐ → 買う → 強くなった」を数回味わってから、
	//       **アップグレードでは開かない壁**に当たるほうが、対比が効く。
	//   ★扉は 24m 手前から画面に見えてくる（＝ 116m まで走れば「あれは何だ？」が起きる）
	var GATE_M    = 140;    // ★★扉はここに立っている（メートル）

	// ============================================================
	// ★★★鍵をいつ出すか —— **距離ではなく「扉を見たか」で決める**
	//
	//   ⚠ ★★2026-08-16、実装中に**確定仕様どうしの矛盾**が見つかった。
	//
	//     island さんの指定は2つあった:
	//       ① 扉は**鍵が無ければ絶対に通れない**
	//       ② 鍵は「**扉発見後**に探索できる距離帯」から出す
	//
	//     ★これを「扉より**先の距離**（400m〜）」と読んで作ったところ、
	//       ★★★**扉で必ず止まるので 400m には永久に届かない ＝ 輪が閉じない**。
	//       （★実測: 60本走らせて鍵が出たのは 10%。しかもそれは
	//         テストでスタミナを無限にしていたから届いただけだった）
	//
	//   → ★★「**扉発見後に探索できる距離帯**」を素直に読み直すと、
	//       それは **0〜300m（扉の手前）を、扉を見たあとのランで走るとき**。
	//     ★これなら ①も②も両方守れる:
	//       ・扉を見る前は鍵が出ない  → 「何だこれ？」が先に来る（輪は逆転しない）
	//       ・扉を見たあとは手前に出る → 拾える（輪が閉じる）
	//
	//   ★★★この読み替えは**島さんに報告すること**（勝手に決めた線引きではないが、
	//     仕様の文面そのままではないため）
	// ============================================================
	var KEY_MIN_M = 40;     // ★これより手前には出さない（★走り出してすぐは出さない）
	// ★★これは「**鍵の候補を作る1回あたり**の抽選確率」。
	//   ★★**ラン全体の遭遇率ではない**（★どこまで走れるかに依存する）。
	//
	// ★★★この値は**実測で決めた**（2026-08-16）。★当てずっぽうではない
	//
	//   観測事実 … 扉を見たあとのランで、抽選が回るのは **1ランに中央7回・平均6.3回**
	//               （288ラン実測。40m〜扉140m の 100m ぶんしか有効区間が無いため）
	//               → 2% だと1ランで出る確率は **12%**、拾うまで**中央6ラン**、
	//                 ★**10回に1回は 19ラン以上**「扉に当たって終わる」を繰り返す
	//   仮説     … 有効な抽選回数が少なすぎるので、1回あたりの確率が低すぎた
	//   変更     … 2% → **6%**（1ランで出る確率 32% / 中央2ラン / 10回に9回は6ラン以内）
	//   ★目標は「扉を見たあと**数ラン**」。★★1ラン目で必ず出るのは**濃すぎる**ので避けた
	var KEY_RATE  = 0.06;
	var KEY_TRY_GAP = 120;  // ★何ドット進むごとに1回抽選するか

	// ============================================================
	// ■■■ ★★★キャンプ・HP・死亡（2026-08-16 / Phase D）■■■
	// ============================================================
	//
	//   島さん（2026-08-16）:
	//   > 「⛺はUIボタンではなく、**ゲーム世界に存在するチェックポイント／キャンプ**」
	//   > 「ここまでの旅を確定して安全を取るか、リスクを背負って先へ進むか」
	//
	// ■ ★★3つのゲージの役割を**はっきり分ける**（島さんの指定）
	//
	//     スタミナ … **どれだけ長く旅を続けられるか**  → 0 で「撤退」（★稼ぎは全部残る）
	//     HP       … **どれだけミスに耐えられるか**    → 0 で「死亡」（★★未確定分を全部失う）
	//     倍率     … **リスクを取ることで積み上がる収益**
	//
	//   ★★★だから **ぶつかってもスタミナは減らさない**（島さんの判断 2026-08-16）。
	//     ★減らすと2つのゲージが同じ方向に動いて、**分けた意味が消える**
	//
	// ■ ★★キャンプに着いたら**世界が止まって選ぶ**
	//
	//     キャンプする   … ★**そこで旅を終えて店へ戻る**（成果確定）
	//     このまま進む   … ★倍率もHPもそのまま。★さらに奥へ（★死ぬと全部失う）
	//
	//   ★★「キャンプ＝ランを終える」は島さんの判断（2026-08-16）。
	//     ★スタミナを回復して走り続けられる形にすると、**無限に走れて店に戻らない**
	//
	// ■ ★★下の数字は「初期値」であって仕様ではない（★実測で決め直す）
	// ============================================================
	// ★★★2026-08-16、島さんの指定で**保留**にした（扉と同じ）。
	//   ★★1 に戻すと キャンプ・HP・死亡 がまとめて復活する
	//   ★0 のあいだは、ぶつかったときのスタミナ減（昔の形）に戻る
	var CAMP_ON  = 0;     // ★1 にするとキャンプ・HP・死亡が戻る
	var CAMP_M   = 100;   // ★★何メートルごとにキャンプがあるか。★**初期値**
	//   ★実測: 1ランで届く距離は Lv0 で中央113m / Lv3 で中央231m
	//     → 100m なら Lv0 で1つ目、Lv3 で2〜3つ目に出会う
	//   ★★扉(140m)が「1つ目のキャンプの直後」に来る＝**確定してから壁に挑む**
	var HP_MAX   = 5;     // ★★何回ぶつかったら死ぬか
	//   ★★★これは**実測で決めた**（2026-08-16）。★当てずっぽうではない
	//
	//     観測事実 … HP3 だと Lv0 の死亡率が **21〜50%**。★遊び始めてすぐ、
	//                 まだ HP の意味も分からないうちに全部失う
	//     仮説     … 1ランに 1.8〜4.9回ぶつかるので、3 では最初の1本すら持たない
	//     変更     … 3 → **5**
	//     再測定   … 下（★24本ずつ・毎秒1.3連打）
	//
	//       HP   Lv0の死亡率   Lv3「HPが1でキャンプ」   Lv3「絶対キャンプしない」
	//        3      21〜50%              682コイン                     0コイン
	//        4       8〜33%              364コイン                     0コイン
	//     ★  5       0〜 4%          ★★763コイン                   203コイン
	//
	//   ★★5 だと「遊び始めは死なない／育つと判断が要る」になる。
	//     ★Lv3 で「HPが1になったらキャンプ」が **763** と、
	//       毎回キャンプ(318)・絶対しない(203) の**どちらより明確に良い** ＝ 判断に意味がある
	//   ★実測（気楽に遊ぶ人・毎秒1.3連打）: 1ランに Lv0 1.8回 / Lv3 4.9回 ぶつかる
	//   ★★3 だと Lv1 あたりから「あと1回で死ぬ」が起きる＝**キャンプする理由になる**
	//   ★5 にすると、ほぼ死なずスタミナ切れで終わる＝**キャンプが要らなくなる**
	var CAMP_STOP_MS = 250;   // ★キャンプに着いてから選べるようになるまで（誤タップよけ）
	// ★★死んだらどうなるか。★★これは「まだ決めない」と島さんが言った所（2026-08-16）
	//   1 = ラン完全終了（★島さんの第一候補）／ 0 = 最後のキャンプから再開
	//   ★★実機で確かめてから決める。**ここを1行変えれば切り替わる**
	var DEATH_ENDS_RUN = 1;
	// ★HP の表示（★スタミナバーのすぐ下に、HP_MAX 個の四角）
	var HP_BLOCK_W = 5, HP_BLOCK_H = 3, HP_GAP = 1;
	var C_HP_ON = 17, C_HP_OFF = 5;    // 17=赤 / 5=炭
	// ★★扉で止められたとき、リザルトへ行く前に見せる時間（→ `blockedByGate()`）
	var GATE_STOP_MS = 900;

	// ============================================================
	// ■■■ ★★報酬フィードバック（2026-08-15 島さんの実機フィードバック）■■■
	// ============================================================
	//
	//   島さん「走る → 数値が増える → **でも画面上では何が起きたか分からない**」
	//
	//   ★★狙いは「ポップアップを足すこと」ではなく、
	//     **「越えると倍率が育つんだ。じゃあ次も越えたい」**を目に見えるようにすること。
	//
	//   ★★★**出す数字は、必ず「実際に変わった量」から作ること**（島さんの指定）。
	//     表示だけ別に直書きすると、あとで倍率を変えたときに
	//     **「実際は +1.0 なのに画面は +0.5」**という同期バグが必ず起きる
	var POP_ON       = 1;     // 0 にするとポップアップが出なくなる
