	//
	//   > 島さん「スケーターが飛んだ時に✨のエフェクトがほしい」
	//   > ★★島さん「**飛んだ後がいい。飛んだ軌跡を描くように。なので手前から後ろ**」
	//
	//   ★★**跳んだ瞬間に一度だけ散らすのではありません。**
	//     ★滞空しているあいだ、**通った道に粒を置いていく**ので、
	//     ★★**跳躍の弧が、そのまま光の跡**になります。
	//   ★★★置いた粒は**世界に留まります**（★地面とまったく同じ速さで後ろへ流れる）
	//     ＝ ★島さんの「手前から後ろ」。★★主役だけが前へ進み、跡は置き去りになる
	//
