	//   > ★★**島さん「市松に間引かないでください。半透明は追加してよいです。」**
	//
	//   ★★★★**この作品で初めて「半透明」を使います。**
	//     ★はじめ AI は決まり（★半透明を使わない）に従って**市松に間引いて**作りましたが、
	//     ★★**島さんが見て「間引かないでほしい。半透明を足してよい」と決めました**。
	//
