	//     ★これまで半透明を禁じてきたのは「**この世界に無い色が生まれる**」ため
	//       （★暗転・白い光・フラッシュは、どれも横の行をベタ塗りして作っています）。
	//     ★★★**きらめきだけが例外**です（★エンディングの挿し絵と同じ扱い）。
