	//   ★★**大きくしすぎると「軌跡」に見えなくなります**（★弧がばらけるため）
	var SPARK_JITTER_X = 2;  // ★よこのばらつき（★±このドット）
	var SPARK_JITTER_Y = 2;  // ★たてのばらつき（★±このドット）

