	var DUST_Y     = 2;    // ★★出る高さ（★地面から何ドット上 ＝ ボードの面のあたり）
	var DUST_SPREAD = 3;   // ★出る場所のよこのばらつき（★±このドット ＝ ボードの幅ぶん）
	var DUST_HELD  = 64;   // ★同時に出る数の上限（★溜まり続けないように）
	                       //   ★★★2026-08-31、24 → 40 → **64**（★トラックの火花が出続けるため）
	                       //   ★★狭いと、★★★**火花が跳ぶけむり・着地のけむりを押し出します**
