	var DUST_DIM_RATE  = 0.3;   // ★★0=ぜんぶ濃い / 0.5=半分が薄い / 1=ぜんぶ薄い
	var DUST_DIM_ALPHA = 0.5;   // ★★★薄い粒の濃さ
